// L30 と検査は「比べた回が reframed なら prior: 捉え直し」を許す。どちらが実態か。
func TestProbeReframedPriorWithoutPlans(t *testing.T) {
	// 回 1: 採択を plans で覆う (被覆の検査を通すため plan_ref は使わず素直に)
	// 回 2: reframed だが plans 無し + 採択は回 3 の plan_ref で覆う
	// 回 3: fix-derived / prior: 捉え直し / prior_run: 2
	src := recurrenceReframedThenRecordYAML("      status: detected\n" +
		"      evidence:\n" +
		"        - condition: fix-derived\n" +
		"          finding_id: 1\n" +
		"          prior_run: 2\n" +
		"          prior: 捉え直し\n" +
		"          reason: 回 2 の捉え直しの軸の別のマス\n")
	// 回 2 の plans ブロックを取り除く
	i := strings.Index(src, "    plans:\n      - problem_id: P2")
	if i < 0 {
		t.Fatal("回 2 の plans が見つからない")
	}
	j := strings.Index(src[i:], "  - date: \"2026-09-01\"")
	if j < 0 {
		t.Fatal("回 3 の先頭が見つからない")
	}
	noPlans := src[:i] + src[i+j:]
	files, read := recordFiles(t, noPlans)
	for _, p := range reviewTriageRecordProblems(files, read) {
		t.Logf("問題: %s", p)
	}
}
